import{_ as e,c as a,o,ae as i}from"./chunks/framework.Cd-3tpCq.js";const u=JSON.parse(`{"title":"Upload Customizable-Option File","description":"","frontmatter":{"outline":false,"examples":[{"id":"upload-customizable-file","title":"Upload a Customizable-Option File","description":"Stage a file for a file-type customizable option and get a token. Send the token on Add to Cart as customizableOptions with the option id.","request":"POST /api/shop/customizable-option-files\\nContent-Type: multipart/form-data\\nX-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxx\\nAuthorization: Bearer <token>\\n\\nproduct_id=2977\\noption_id=11\\nfile=@/path/to/spec.pdf\\n","response":"{\\n  \\"token\\": \\"q8f2c1a0…48-char-token\\",\\n  \\"fileName\\": \\"spec.pdf\\",\\n  \\"optionId\\": 11\\n}\\n","commonErrors":[{"error":"400 Bad Request","cause":"The option is not a file option, or the file is missing / wrong extension / too large","solution":"Use a file option id and a file whose extension is in the option's supported list"},{"error":"403 Forbidden","cause":"The staged file is referenced by a different cart on Add to Cart","solution":"Upload the file with the same cart/customer token you use for Add to Cart"},{"error":"404 Not Found","cause":"The product id does not exist","solution":"Use a valid product id"}]}]},"headers":[],"relativePath":"api/rest-api/shop/cart/upload-customizable-file.md","filePath":"api/rest-api/shop/cart/upload-customizable-file.md"}`),s={name:"api/rest-api/shop/cart/upload-customizable-file.md"};function d(n,t,r,l,p,h){return o(),a("div",null,t[0]||(t[0]=[i(`<h1 id="upload-customizable-option-file" tabindex="-1">Upload Customizable-Option File <a class="header-anchor" href="#upload-customizable-option-file" aria-label="Permalink to &quot;Upload Customizable-Option File&quot;">​</a></h1><p>Stage a file for a <strong>file-type</strong> customizable option. A file cannot travel in a JSON body, so uploading is a separate REST call that returns a short-lived <strong>token</strong>; <a href="/api/rest-api/shop/cart/add-to-cart.html">Add to Cart</a> then references the token. This keeps Add to Cart pure JSON, so it works on both REST and GraphQL.</p><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  read[&quot;1. Read option id&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  up[&quot;2. Upload (REST)&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  add[&quot;3. Add to cart&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  cart[&quot;File in cart&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  order[&quot;File to order&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  read --&gt; up --&gt; add --&gt; cart --&gt; order</span></span></code></pre></div><ol><li><strong>Read the option</strong> from the product&#39;s <code>customizableOptions</code> (<a href="/api/rest-api/shop/products/get-product.html">Get Product</a>) — a <code>file</code>-type option carries its <code>id</code> and the allowed extensions.</li><li><strong>Upload the file here</strong> (this endpoint) → you get a short-lived <code>token</code>. This is the only REST-required step; GraphQL cannot carry a binary.</li><li><strong>Add to cart</strong> with the token as that option&#39;s value — over <a href="/api/rest-api/shop/cart/add-to-cart.html">REST</a> or GraphQL. The mutation carries only the token string.</li><li><strong>Core owns the rest</strong> — the file is stored with the cart, then moved to the order automatically when the order is placed.</li></ol><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/shop/customizable-option-files</span></span></code></pre></div><h2 id="request-multipart-form-data" tabindex="-1">Request (multipart/form-data) <a class="header-anchor" href="#request-multipart-form-data" aria-label="Permalink to &quot;Request (multipart/form-data)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>product_id</code></td><td>integer</td><td>Yes</td><td>The product that owns the option</td></tr><tr><td><code>option_id</code></td><td>integer</td><td>Yes</td><td>The <code>file</code>-type customizable option id (from the product&#39;s <code>customizableOptions</code>)</td></tr><tr><td><code>file</code></td><td>file</td><td>Yes</td><td>The file — its extension must be in the option&#39;s supported extensions and within the size limit</td></tr></tbody></table><p>Send the storefront key and the same cart/customer Bearer token you will use for Add to Cart.</p><h2 id="response-201" tabindex="-1">Response (201) <a class="header-anchor" href="#response-201" aria-label="Permalink to &quot;Response (201)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>token</code></td><td>string</td><td>Short-lived reference to the staged file</td></tr><tr><td><code>fileName</code></td><td>string</td><td>The original file name</td></tr><tr><td><code>optionId</code></td><td>integer</td><td>The option the file is for</td></tr></tbody></table><h2 id="then-add-to-cart" tabindex="-1">Then add to cart <a class="header-anchor" href="#then-add-to-cart" aria-label="Permalink to &quot;Then add to cart&quot;">​</a></h2><p>Send the token as the option&#39;s value on <a href="/api/rest-api/shop/cart/add-to-cart.html">Add to Cart</a>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;customizableOptions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;11&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;token&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }</span></span></code></pre></div><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>The token expires after a short window (default 60 minutes). If it expires, upload again.</li><li>The file is stored with the cart on Add to Cart and is moved to the order automatically when the order is placed — you do not save it separately.</li><li>The upload is <strong>REST-only</strong> (binary); Add to Cart with the token works on REST and GraphQL.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/cart/add-to-cart.html">Add to Cart</a> — add a product of any type to the cart</li><li><a href="/api/rest-api/shop/products/get-product.html">Get Product</a> — one product&#39;s full detail with its relations inlined</li></ul>`,19)]))}const f=e(s,[["render",d]]);export{u as __pageData,f as default};
